const text={pt:{navJourney:'Percurso',navWorkshop:'Oficina',navCare:'Cuidado',eyebrow:'Uma iniciação à internet',title:'Conhecimento para navegar por dentro e por fora.',intro:'Eu encontrei uma semente no meio dos dados. Você me ajuda a descobrir de onde ela veio?',begin:'Começar com o pequeno robô',time:'15 minutos',timeHelp:'no seu ritmo',account:'Sem cadastro',accountHelp:'nada é enviado',local:'Progresso local',localHelp:'guardado neste aparelho',pathLabel:'Seu primeiro mapa',pathTitle:'Quatro gestos para não se perder',s1t:'Pare e observe',s1p:'Antes do clique, leia o endereço, reconheça quem publicou e perceba o que a página quer de você.',s2t:'Pergunte melhor',s2p:'Uma busca melhora quando ganha contexto, palavras específicas e uma pergunta que você realmente deseja responder.',s3t:'Cruze caminhos',s3p:'A Wikipédia oferece pistas. Abra as referências, compare fontes e descubra onde cada afirmação começou.',s4t:'Cuide de você',s4p:'Se o conteúdo apertar o peito, pare. Feche a aba, respire, procure alguém. Conhecer também é saber interromper.',practice:'Praticar este gesto',labLabel:'Oficina de pistas',labTitle:'Investigue uma informação',example:'Exemplo fictício',claim:'“Um estudo prova que usar telas sempre melhora a aprendizagem.”',question:'O que você verificaria primeiro?',c1:'Quem escreveu e qual é sua formação?',c2:'Onde está o estudo citado?',c3:'A data e o contexto continuam válidos?',c4:'Se a frase combina com o que já penso?',check:'Conferir escolhas',careLabel:'Uma pausa também ensina',careTitle:'A internet não precisa ser atravessada sozinho.',careText:'O WikiAcolhe é um espaço educativo e reflexivo. Não é terapia, diagnóstico ou atendimento de emergência. Se algo lhe fizer mal, afaste-se da tela e converse com uma pessoa de confiança ou um profissional.',breathe:'Fazer uma pausa de 20 segundos',guideLabel:'Mensagem do viajante',guideTitle:'Aqui você não precisa saber tudo.',guideText:'Escolha um gesto, experimente e volte quando quiser. Eu guardo seu progresso somente neste aparelho.',guideGo:'Encontrar o primeiro gesto',credit:'Idealizado por Sidiney Rodrigues. Projeto educacional aberto, independente e sem coleta de dados.',reset:'Recomeçar percurso'},en:{navJourney:'Journey',navWorkshop:'Workshop',navCare:'Care',eyebrow:'An initiation to the internet',title:'Knowledge to navigate outside and within.',intro:'I found a seed among the data. Will you help me discover where it came from?',begin:'Start with the little robot',time:'15 minutes',timeHelp:'at your own pace',account:'No account',accountHelp:'nothing is sent',local:'Local progress',localHelp:'stored on this device',pathLabel:'Your first map',pathTitle:'Four gestures to avoid getting lost',s1t:'Pause and observe',s1p:'Before clicking, read the address, identify the publisher and notice what the page wants from you.',s2t:'Ask better',s2p:'A search improves with context, specific words and a question you truly want to answer.',s3t:'Cross paths',s3p:'Wikipedia offers clues. Open the references, compare sources and find where each claim began.',s4t:'Take care of yourself',s4p:'If content makes you feel overwhelmed, pause. Close the tab, breathe, find someone. Knowing also means knowing when to stop.',practice:'Practice this gesture',labLabel:'Clue workshop',labTitle:'Investigate a claim',example:'Fictional example',claim:'“A study proves that screens always improve learning.”',question:'What would you check first?',c1:'Who wrote it and what is their expertise?',c2:'Where is the cited study?',c3:'Are the date and context still valid?',c4:'Whether the claim agrees with me?',check:'Check choices',careLabel:'A pause also teaches',careTitle:'You do not have to cross the internet alone.',careText:'WikiAcolhe is an educational and reflective space. It is not therapy, diagnosis or emergency care. If something harms you, step away from the screen and talk to someone you trust or a professional.',breathe:'Take a 20-second pause',guideLabel:'Message from the traveler',guideTitle:'You do not need to know everything here.',guideText:'Choose one gesture, try it and return whenever you wish. I keep your progress only on this device.',guideGo:'Find the first gesture',credit:'Conceived by Sidiney Rodrigues. An open, independent educational project with no data collection.',reset:'Restart journey'}};
Object.assign(text.pt,{donationIntro:'Este projeto nasceu do desejo de ensinar e cuidar. Se ele tocou você,',donationLink:'considere doar diretamente ao Hospital Pequeno Príncipe',donationNote:'Iniciativa voluntária, independente e sem intermediação financeira.'});
