let lang=localStorage.getItem('wikiacolhe-lang')||'pt';let done=JSON.parse(localStorage.getItem('wikiacolhe-progress')||'[]');
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function renderLang(){document.documentElement.lang=lang==='pt'?'pt-BR':'en';$$('[data-i18n]').forEach(el=>el.textContent=text[lang][el.dataset.i18n]);$('#language').textContent=lang==='pt'?'EN':'PT';$('#language').setAttribute('aria-label',lang==='pt'?'Mudar idioma para inglês':'Change language to Portuguese');renderProgress()}
function renderProgress(){$$('.step').forEach((el,i)=>el.classList.toggle('done',done.includes(i)));$('#progress').value=done.length;$('#progressText').textContent=lang==='pt'?`${done.length} de 4`:`${done.length} of 4`}
$('#language').onclick=()=>{lang=lang==='pt'?'en':'pt';localStorage.setItem('wikiacolhe-lang',lang);renderLang()};
$('#begin').onclick=()=>$('#guide').showModal();$('.close').onclick=()=>$('#guide').close();$('#guideGo').onclick=()=>{$('#guide').close();$('#percurso').scrollIntoView()};
$$('.step-action').forEach((b,i)=>b.onclick=()=>{done=done.includes(i)?done.filter(x=>x!==i):[...done,i].sort();localStorage.setItem('wikiacolhe-progress',JSON.stringify(done));renderProgress();b.closest('.step').focus?.()});
$('#checklist').onsubmit=e=>{e.preventDefault();const picked=[...new FormData(e.target).values()];const good=['author','study','date'].filter(x=>picked.includes(x)).length;$('#feedback').textContent=lang==='pt'?(good===3?'Ótimo: você procurou autoria, evidência e contexto. A concordância pessoal não confirma uma informação.':`Você encontrou ${good} de 3 pistas essenciais. Procure autoria, estudo e contexto.`):(good===3?'Great: you checked authorship, evidence and context. Personal agreement does not verify a claim.':`You found ${good} of 3 essential clues. Look for authorship, study and context.`)};
let timer;$('#breathe').onclick=()=>{clearInterval(timer);let n=20;const out=$('#breathStatus');out.textContent=lang==='pt'?`Respire devagar. ${n}`:`Breathe slowly. ${n}`;timer=setInterval(()=>{n--;out.textContent=n>0?(lang==='pt'?`Respire devagar. ${n}`:`Breathe slowly. ${n}`):(lang==='pt'?'Você voltou. Continue apenas se quiser.':'You are back. Continue only if you wish.');if(n<=0)clearInterval(timer)},1000)};
$('#reset').onclick=()=>{done=[];localStorage.removeItem('wikiacolhe-progress');renderProgress()};renderLang();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
